@PostMapping("/api/surpay/webhook")
public ResponseEntity<Map<String, Object>> webhook(@RequestBody byte[] rawBody,
                                                     @RequestHeader("X-Surpay-Signature") String signature) throws Exception {
    String secret = System.getenv("SURPAY_WEBHOOK_SECRET");
    Mac mac = Mac.getInstance("HmacSHA256");
    mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
    byte[] expectedBytes = mac.doFinal(rawBody);
    String expected = Base64.getEncoder().encodeToString(expectedBytes);

    if (!MessageDigest.isEqual(signature.getBytes(StandardCharsets.UTF_8), expected.getBytes(StandardCharsets.UTF_8))) {
        return ResponseEntity.status(401).body(Map.of("ok", false));
    }

    JsonNode event = new ObjectMapper().readTree(rawBody);
    if ("paid".equals(event.path("state").asText())) {
        // actualizar pedido interno a pagado
        // orderService.markPaid(event.path("order_id").asText());
    }
    return ResponseEntity.ok(Map.of("ok", true));
}

