public async Task<IActionResult> SurpayWebhook()
{
    using var reader = new StreamReader(Request.Body, Encoding.UTF8);
    var rawBody = await reader.ReadToEndAsync();
    var signature = Request.Headers["X-Surpay-Signature"].ToString();
    var secret = Environment.GetEnvironmentVariable("SURPAY_WEBHOOK_SECRET") ?? "";

    using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(secret));
    var expected = Convert.ToBase64String(hmac.ComputeHash(Encoding.UTF8.GetBytes(rawBody)));
    if (!CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(signature), Encoding.UTF8.GetBytes(expected)))
    {
        return Unauthorized(new { ok = false });
    }

    var event = JsonSerializer.Deserialize<JsonElement>(rawBody);
    if (event.TryGetProperty("state", out var stateElement) && stateElement.GetString() == "paid")
    {
        // actualizar pedido interno a pagado
        // await orderService.MarkPaidAsync(event.GetProperty("order_id").GetString());
    }

    return Ok(new { ok = true });
}

func SurpayWebhook(w http.ResponseWriter, r *http.Request) {
    rawBody, _ := io.ReadAll(r.Body)
    signature := r.Header.Get("X-Surpay-Signature")
    secret := os.Getenv("SURPAY_WEBHOOK_SECRET")

    mac := hmac.New(sha256.New, []byte(secret))
    mac.Write(rawBody)
    expected := base64.StdEncoding.EncodeToString(mac.Sum(nil))

    if !hmac.Equal([]byte(signature), []byte(expected)) {
        w.WriteHeader(http.StatusUnauthorized)
        w.Write([]byte(`{"ok":false}`))
        return
    }

    var event map[string]any
    _ = json.Unmarshal(rawBody, &event)
    if state, _ := event["state"].(string); state == "paid" {
        // actualizar pedido interno a pagado
        // orderService.MarkPaid(event["order_id"].(string))
    }

    w.Header().Set("Content-Type", "application/json")
    w.Write([]byte(`{"ok":true}`))
}

