document.addEventListener("DOMContentLoaded", function () {
    const codeBlocks = document.querySelectorAll("pre.sp-code code");
    const runtimeOrigin = window.location.origin;
    codeBlocks.forEach((codeEl) => {
        const original = codeEl.textContent || "";
        const withRuntimeDomain = original.replaceAll("https://TU-DOMINIO", runtimeOrigin);
        const normalized = withRuntimeDomain.replace(/\r\n/g, "\n").replace(/^\n+|\n+$/g, "");
        const lines = normalized.split("\n");

        let minIndent = null;
        lines.forEach((line) => {
            if (!line.trim()) return;
            const match = line.match(/^\s*/);
            const indent = match ? match[0].length : 0;
            minIndent = minIndent === null ? indent : Math.min(minIndent, indent);
        });

        if (minIndent && minIndent > 0) {
            const dedented = lines.map((line) => (line.trim() ? line.slice(minIndent) : "")).join("\n");
            codeEl.textContent = dedented;
        } else {
            codeEl.textContent = normalized;
        }
    });

    const tabGroups = document.querySelectorAll("[data-tab-group]");
    tabGroups.forEach((group) => {
        const groupName = group.getAttribute("data-tab-group");
        const buttons = group.querySelectorAll("button[data-tab-target]");
        const panels = document.querySelectorAll('[data-tab-panel="' + groupName + '"]');

        const activate = (target) => {
            buttons.forEach((btn) => {
                btn.classList.toggle("is-active", btn.getAttribute("data-tab-target") === target);
            });
            panels.forEach((panel) => {
                panel.classList.toggle("is-active", panel.getAttribute("data-tab-id") === target);
            });
        };

        buttons.forEach((btn) => {
            btn.addEventListener("click", function () {
                activate(btn.getAttribute("data-tab-target"));
            });
        });
    });
});
